
'use strict';
const U=[{"en":"Who am I?","ru":"Кто я?","summary":"Личность, привычки, изменения в жизни и британская культура","lessons":[{"title":"Present Simple или Continuous?","rule":"Present Simple — привычки и факты (usually, every day). Present Continuous — действие прямо сейчас или временная ситуация (now, at the moment). Для Continuous нужны am/is/are + глагол с -ing.","example":"My brother usually walks to school, but today he is cycling.","translate":"Мой брат обычно ходит в школу пешком, но сегодня едет на велосипеде.","tip":"Сначала найди слова-подсказки: every day или now.","questions":[{"prompt":"Look! Anna ___ a picture now.","options":["paints","is painting","paint"],"answer":1,"why":"Look! и now показывают действие сейчас: is painting.","hint":"Событие происходит прямо сейчас."},{"prompt":"My parents ___ coffee every morning.","options":["drink","are drinking","drinks"],"answer":0,"why":"Every morning указывает на привычку; parents — множественное число: drink.","hint":"Every morning — обычно или прямо сейчас?"},{"prompt":"He ___ tennis on Saturdays.","options":["play","is playing","plays"],"answer":2,"why":"Для he в Present Simple добавляется -s: plays.","hint":"He + Present Simple требует окончания -s."}],"skill":"Грамматика","id":"u1l1","unit":0},{"title":"Глаголы состояния: love, know, want","rule":"Некоторые глаголы выражают состояние, а не действие: know, like, love, want, understand. В основных значениях они обычно не используются в Continuous.","example":"I know the answer, but I do not understand the question.","translate":"Я знаю ответ, но не понимаю вопрос.","tip":"Спроси себя: это процесс прямо сейчас или чувство/знание?","questions":[{"prompt":"Choose the natural sentence.","options":["I am knowing her name.","I know her name.","I knowing her name."],"answer":1,"why":"Know — глагол состояния, обычно Present Simple.","hint":"Know обозначает знание."},{"prompt":"She ___ chocolate.","options":["is loving","love","loves"],"answer":2,"why":"Love в значении «любить» обычно употребляется в Simple.","hint":"She в Present Simple."},{"prompt":"We ___ a bigger classroom.","options":["want","are wanting","wants"],"answer":0,"why":"Want — глагол состояния, с we нужна форма want.","hint":"We — не he/she/it."}],"skill":"Грамматика","id":"u1l2","unit":0},{"title":"Как рассказать о себе","rule":"Удобная схема: имя и возраст → характер → интересы → то, что делаешь сейчас. Используй I am..., I usually..., I enjoy... и I am learning....","example":"I am curious and friendly. I enjoy music and I am learning to play the guitar.","translate":"Я любознательная и дружелюбная. Мне нравится музыка, и я учусь играть на гитаре.","tip":"В рассказе о себе соединяй две-три простые мысли, а не одну длинную.","questions":[{"prompt":"Which word means «общительный»?","options":["shy","sociable","rude"],"answer":1,"why":"Sociable — общительный; shy — застенчивый.","hint":"Вспомни слово social."},{"prompt":"Choose the best sentence.","options":["I am interested in music.","I interested music.","I am interesting at music."],"answer":0,"why":"Говорим be interested in something.","hint":"Нужны am и предлог in."},{"prompt":"She is very ___. She always arrives on time.","options":["punctual","lazy","noisy"],"answer":0,"why":"Punctual — пунктуальный, приходит вовремя.","hint":"On time — вовремя."}],"skill":"Лексика и речь","id":"u1l3","unit":0}],"read":{"text":"Mila lives in a small town. She usually walks to school with her sister, but this week she is taking the bus because her bicycle is broken. She likes music and plays the piano.","prompt":"Why is Mila taking the bus this week?","options":["Her bicycle is broken.","She moved to another city.","She dislikes walking."],"answer":0,"why":"Текст говорит: her bicycle is broken."},"pages":[6,13]},{"en":"Globetrotter!","ru":"Путешественник","summary":"Планы путешествий, информация и электронные письма","lessons":[{"title":"Будущие планы: going to","rule":"Be going to + глагол — намерение или план: I am going to visit my aunt. Не забудь am/is/are перед going to.","example":"We are going to spend our holiday in the mountains.","translate":"Мы собираемся провести каникулы в горах.","tip":"У слова going обязательно есть помощник am/is/are.","questions":[{"prompt":"They ___ visit London next summer.","options":["are going to","is going to","going to"],"answer":0,"why":"С they употребляется are going to.","hint":"They → are."},{"prompt":"I ___ pack my suitcase tonight.","options":["am going to","is going","will to"],"answer":0,"why":"I am going to + начальная форма глагола.","hint":"I → am."},{"prompt":"She is going to ___ a ticket.","options":["bought","buy","buying"],"answer":1,"why":"После going to нужен начальный глагол: buy.","hint":"После to у глагола нет -ing."}],"skill":"Грамматика","id":"u2l1","unit":1},{"title":"Договорённость: Present Continuous","rule":"Present Continuous может обозначать личную договорённость на будущее, особенно с указанием времени: We are meeting on Friday.","example":"I am flying to Kazan on Saturday.","translate":"Я лечу в Казань в субботу (по плану).","tip":"Отличай договорённость от привычки.","questions":[{"prompt":"We ___ our friends at six tomorrow.","options":["meet usually","are meeting","meets"],"answer":1,"why":"Договорённость на завтра: are meeting.","hint":"Есть конкретное время договорённости."},{"prompt":"Anna ___ to the dentist next Monday.","options":["is going","go","are going"],"answer":0,"why":"Anna = she, значит is going.","hint":"Anna = she."},{"prompt":"Which is a future arrangement?","options":["I am meeting Kate tonight.","I meet Kate every week.","I met Kate yesterday."],"answer":0,"why":"Tonight + Present Continuous часто обозначает договорённость.","hint":"Ищи tonight."}],"skill":"Грамматика","id":"u2l2","unit":1},{"title":"Вежливые вопросы в путешествии","rule":"Чтобы узнать информацию, используй Could you tell me...? / I would like to know... / How much does ... cost? Для вежливости добавляй please.","example":"Could you tell me when the bus leaves, please?","translate":"Не могли бы вы сказать, когда отправляется автобус?","tip":"В косвенном вопросе порядок слов прямой: when the bus leaves.","questions":[{"prompt":"Choose the most polite request.","options":["Give me a room!","Could I have a room, please?","Room now."],"answer":1,"why":"Could I have ... please? — вежливая просьба.","hint":"Слова could и please помогают."},{"prompt":"How much ___ the ticket cost?","options":["do","does","is"],"answer":1,"why":"Ticket — одно число, в Present Simple вопрос начинается с does.","hint":"Ticket = it."},{"prompt":"Select a correct email opening.","options":["Dear Sir or Madam,","Hey you!!!","Give info"],"answer":0,"why":"Dear Sir or Madam — нейтрально-вежливое начало.","hint":"Для официального письма выбирай нейтральный стиль."}],"skill":"Общение","id":"u2l3","unit":1},{"title":"Пишем вежливое письмо: formal / informal","rule":"В официальном электронном письме используй Dear Sir or Madam, Could you tell me…?, Yours faithfully. В письме знакомому подходят Hi, Thanks for your message, See you soon. Главное — понять, кому ты пишешь и зачем.","example":"Dear Sir or Madam, Could you tell me the price of the tickets?","translate":"Уважаемые господа, не могли бы вы сообщить стоимость билетов?","tip":"Незнакомой организации — вежливый тон; другу — дружеский.","questions":[{"prompt":"Which opening is suitable for a formal enquiry?","options":["Hey, mate!","Dear Sir or Madam,","Yo!"],"answer":1,"why":"Так обращаются к незнакомому адресату в официальном письме.","hint":"Письмо в организацию."},{"prompt":"Choose the polite question.","options":["Tell me the price now!","Could you tell me the price, please?","You price!"],"answer":1,"why":"Could you…? — вежливая просьба.","hint":"Сравни повеление и вопрос."},{"prompt":"Which ending suits an email to your friend?","options":["See you soon,","Yours faithfully,","To whom it may concern"],"answer":0,"why":"See you soon — дружеское завершение.","hint":"Подумай, как попрощаться с другом."}],"skill":"Письмо","id":"u2l4","unit":1}],"read":{"text":"Leo and his family are going to spend three days in a national park. They have booked a small cabin. On Saturday, they are meeting a guide at ten in the morning.","prompt":"Where will Leo stay?","options":["At a campsite.","In a small cabin.","In a hotel by the sea."],"answer":1,"why":"Family have booked a small cabin."},"pages":[14,21]},{"en":"Growing up","ru":"Взросление","summary":"Школа, воспоминания, чувства и взросление","lessons":[{"title":"Past Simple: события в прошлом","rule":"Past Simple показывает завершившееся событие в прошлом: yesterday, last year, ago. Правильные глаголы получают -ed, неправильные имеют особую форму.","example":"I visited my grandmother yesterday and went to the park.","translate":"Вчера я навестила бабушку и пошла в парк.","tip":"Yesterday = Past Simple; выучи частые неправильные формы.","questions":[{"prompt":"Yesterday I ___ my homework.","options":["do","did","done"],"answer":1,"why":"Прошедшая форма do — did.","hint":"Do — неправильный глагол."},{"prompt":"We ___ at home last Sunday.","options":["stayed","stay","staying"],"answer":0,"why":"Stay — правильный глагол: stayed.","hint":"Last Sunday = прошлое."},{"prompt":"She didn’t ___ the test.","options":["passed","passes","pass"],"answer":2,"why":"После didn’t глагол в базовой форме: pass.","hint":"Didn’t уже показывает прошлое."}],"skill":"Грамматика","id":"u3l1","unit":2},{"title":"Used to: раньше было иначе","rule":"Used to + глагол говорит о привычке или ситуации в прошлом, которой больше нет. После used to нужен глагол без окончания.","example":"I used to be shy, but now I enjoy meeting new people.","translate":"Раньше я стеснялась, а теперь люблю знакомиться.","tip":"Сравнивай past и now.","questions":[{"prompt":"When I was little, I ___ play outside every day.","options":["used to","use","using to"],"answer":0,"why":"Used to — привычка в прошлом.","hint":"Речь о привычке в детстве."},{"prompt":"Choose the correct sentence.","options":["She used to liked cartoons.","She used to like cartoons.","She used like cartoons."],"answer":1,"why":"После used to: like без -ed.","hint":"После to — исходная форма глагола."},{"prompt":"I ___ live here, but I moved away.","options":["used to","am used to","use to"],"answer":0,"why":"Раньше жил здесь, но теперь нет: used to.","hint":"Есть противопоставление раньше / теперь."}],"skill":"Грамматика","id":"u3l2","unit":2},{"title":"Вежливо просим разрешения","rule":"May I...? / Could I...? — вежливо просим разрешения; Can I...? — разговорный вариант. Ответы: Of course. / Sure. / Sorry, not now.","example":"Could I borrow your pen, please? — Of course.","translate":"Можно одолжить твою ручку? — Конечно.","tip":"Различай просьбу и требование.","questions":[{"prompt":"___ I open the window, please?","options":["Could","Mustn’t","Was"],"answer":0,"why":"Could I ... please? — вежливая просьба.","hint":"Просьба звучит мягко."},{"prompt":"Pick a polite answer to a request.","options":["Of course, here you are.","No, silence!","You pen."],"answer":0,"why":"Of course, here you are — вежливое разрешение.","hint":"Скажи «конечно, вот»."}],"skill":"Общение","id":"u3l3","unit":2},{"title":"Bored или boring? Прилагательные -ed / -ing","rule":"Окончание -ed описывает чувство человека: I am bored. Окончание -ing — то, что вызывает чувство: The lesson is boring. Аналогично surprised/surprising, excited/exciting.","example":"The film was exciting, and I was excited.","translate":"Фильм был захватывающим, и я была взволнована.","tip":"Человек чувствует — -ed; ситуация вызывает чувство — -ing.","questions":[{"prompt":"The story was very ___.","options":["interested","interesting","interest"],"answer":1,"why":"История вызывает интерес → interesting.","hint":"Описание самой истории."},{"prompt":"I felt ___ before the exam.","options":["nervous","nervousing","nervoused"],"answer":0,"why":"Nervous — обычное прилагательное, не все эмоции имеют -ed/-ing.","hint":"Не добавляй окончания к любому слову."},{"prompt":"She was ___ when she heard the good news.","options":["surprising","surprised","surprise"],"answer":1,"why":"Человек испытывает удивление → surprised.","hint":"Речь о чувстве человека."}],"skill":"Грамматика","id":"u3l4","unit":2}],"read":{"text":"When Nina was seven, she used to be afraid of speaking in public. Last month she gave a short presentation at school. She practised for several days and felt proud afterwards.","prompt":"What did Nina do last month?","options":["She gave a presentation.","She moved schools.","She won a music prize."],"answer":0,"why":"Last month she gave a short presentation."},"pages":[22,29]},{"en":"Inspiration","ru":"Вдохновение","summary":"Вдохновение, истории о прошлом и порядок событий","lessons":[{"title":"Past Continuous: процесс в прошлом","rule":"Past Continuous — действие, которое продолжалось в определённый момент прошлого. Формула was/were + -ing.","example":"At nine o’clock I was reading a book.","translate":"В девять часов я читала книгу.","tip":"Was с I/he/she, were с we/you/they.","questions":[{"prompt":"At 7 pm yesterday, we ___ dinner.","options":["were having","had every day","was having"],"answer":0,"why":"We were having — процесс в конкретный момент прошлого.","hint":"We → were."},{"prompt":"She ___ when I called.","options":["was sleeping","sleep","were sleeping"],"answer":0,"why":"She = was, процесс в прошлом: was sleeping.","hint":"She → was."},{"prompt":"They ___ football at five.","options":["was playing","were playing","play"],"answer":1,"why":"They → were playing.","hint":"They → were."}],"skill":"Грамматика","id":"u4l1","unit":3},{"title":"Past Simple + Past Continuous","rule":"Past Continuous задаёт фон (долгое действие), Past Simple — короткое событие, которое вмешалось. While часто связывает процессы, when — событие.","example":"I was doing my homework when the phone rang.","translate":"Я делала домашнее задание, когда зазвонил телефон.","tip":"Найди длинное действие и неожиданное короткое событие.","questions":[{"prompt":"I ___ home when I saw a fox.","options":["was walking","walks","were walking"],"answer":0,"why":"Длительный фон в прошлом: was walking.","hint":"I → was."},{"prompt":"While Dad was cooking, I ___ the table.","options":["set","am setting","sets"],"answer":0,"why":"Завершённое действие в прошлом: set (форма прошедшего совпадает).","hint":"While задаёт фон."},{"prompt":"The lights went out while we ___ TV.","options":["watched","were watching","watch"],"answer":1,"why":"Просмотр телевизора продолжался: were watching.","hint":"We → were + -ing."}],"skill":"Грамматика","id":"u4l2","unit":3},{"title":"Как рассказывать интересную историю","rule":"В хорошем рассказе нужны начало (one day), развитие (while, suddenly) и результат (in the end). Смешивай Past Simple и Continuous, чтобы было понятно, что происходило.","example":"One day I was walking home. Suddenly I heard a strange noise.","translate":"Однажды я шла домой. Вдруг услышала странный звук.","tip":"Сначала скажи где и когда, потом — что неожиданно случилось.","questions":[{"prompt":"Which word introduces an unexpected event?","options":["usually","suddenly","every day"],"answer":1,"why":"Suddenly = внезапно.","hint":"В русском — «вдруг»."},{"prompt":"Choose a useful ending marker.","options":["In the end,","Yesterdayly,","Now ago,"],"answer":0,"why":"In the end — в конце концов.","hint":"Используют в конце истории."}],"skill":"Письмо и речь","id":"u4l3","unit":3},{"title":"Связки времени: first, then, suddenly, finally","rule":"Когда пересказываешь историю, показывай порядок событий словами first, then, after that, suddenly, finally. События обычно идут в Past Simple, а фон — в Past Continuous.","example":"I was walking home when suddenly it started to rain. Finally, I reached my house.","translate":"Я шла домой, когда внезапно начался дождь. Наконец я добралась до дома.","tip":"First — начало; suddenly — неожиданный поворот; finally — конец.","questions":[{"prompt":"Which word introduces an unexpected event?","options":["suddenly","usually","never"],"answer":0,"why":"Suddenly означает «вдруг».","hint":"Это неожиданность."},{"prompt":"Which word is best for the end of a story?","options":["first","finally","yesterday"],"answer":1,"why":"Finally — «наконец», часто перед финалом.","hint":"Нужно завершение."},{"prompt":"I was reading when the lights ___ out.","options":["were going","went","go"],"answer":1,"why":"На фоне Past Continuous короткое событие выражено Past Simple.","hint":"Короткое событие в прошлом."}],"skill":"Письмо и речь","id":"u4l4","unit":3}],"read":{"text":"At eight o’clock Ben was drawing in his room when he heard a loud noise outside. He looked through the window and saw a neighbour moving a huge box. Ben helped him carry it.","prompt":"What was Ben doing when he heard the noise?","options":["He was watching TV.","He was drawing.","He was cooking."],"answer":1,"why":"At eight he was drawing."},"pages":[32,39]},{"en":"No place like home","ru":"Нет места лучше дома","summary":"Дом, сравнение и описание фотографий","lessons":[{"title":"Comparatives: сравниваем","rule":"Сравнительная степень: small → smaller, beautiful → more beautiful. При сравнении часто есть than.","example":"My room is brighter than the kitchen.","translate":"Моя комната светлее кухни.","tip":"Односложные прилагательные часто +er; длинные — more.","questions":[{"prompt":"Our flat is ___ than theirs.","options":["big","bigger","biggest"],"answer":1,"why":"Bigger than — сравнительная степень.","hint":"Есть слово than."},{"prompt":"This house is ___ expensive than that one.","options":["more","most","many"],"answer":0,"why":"Для длинного expensive используется more.","hint":"Expensive — длинное прилагательное."},{"prompt":"Today is ___ than yesterday.","options":["coldest","colder","cold"],"answer":1,"why":"Colder than — сравнение двух дней.","hint":"Два объекта → comparative."}],"skill":"Грамматика","id":"u5l1","unit":4},{"title":"Superlatives: самый-самый","rule":"Превосходная степень: tall → the tallest, interesting → the most interesting. Прилагательное good имеет форму the best.","example":"This is the most comfortable chair in our house.","translate":"Это самый удобный стул в нашем доме.","tip":"Не забывай the перед превосходной степенью.","questions":[{"prompt":"It is ___ building in the city.","options":["the tallest","taller","tall"],"answer":0,"why":"The tallest — самый высокий.","hint":"Самый → the + -est."},{"prompt":"This is ___ idea of all.","options":["good","better","the best"],"answer":2,"why":"Good → better → the best.","hint":"Good — неправильная степень."},{"prompt":"She has ___ room in the house.","options":["the most beautiful","more beautiful","beautifuler"],"answer":0,"why":"Beautiful — длинное слово: the most beautiful.","hint":"Нужно «самая красивая»."}],"skill":"Грамматика","id":"u5l2","unit":4},{"title":"Who, which, where: уточняем","rule":"Who относится к людям, which — к предметам или животным, where — к местам. Придаточное помогает уточнить, о чём речь.","example":"This is the café where we met.","translate":"Это кафе, где мы встретились.","tip":"Вопрос: человек, предмет или место?","questions":[{"prompt":"This is the girl ___ lives next door.","options":["which","where","who"],"answer":2,"why":"Who относится к человеку.","hint":"Girl — человек."},{"prompt":"I bought a book ___ explains space.","options":["which","where","who"],"answer":0,"why":"Which относится к книге.","hint":"Book — предмет."},{"prompt":"That is the house ___ my aunt lives.","options":["who","where","which"],"answer":1,"why":"Where обозначает место.","hint":"House — место."}],"skill":"Грамматика","id":"u5l3","unit":4},{"title":"Too и enough: описываем комнату и фото","rule":"Too + прилагательное значит «слишком»: too small. Enough после прилагательного значит «достаточно»: big enough. Для описания фото используй in the foreground, in the background, on the left, on the right.","example":"The room is too small, but it is bright enough.","translate":"Комната слишком маленькая, но достаточно светлая.","tip":"Too — чрезмерно; enough — достаточно.","questions":[{"prompt":"This suitcase is ___ heavy to carry.","options":["enough","too","many"],"answer":1,"why":"Too heavy — слишком тяжёлый.","hint":"Слишком."},{"prompt":"The desk is big ___ for two laptops.","options":["too","enough","many"],"answer":1,"why":"После прилагательного big ставим enough.","hint":"Enough идёт после adjective."},{"prompt":"What does “in the background” mean?","options":["на переднем плане","на заднем плане","внизу"],"answer":1,"why":"In the background — на заднем плане.","hint":"Background — дальний план."}],"skill":"Грамматика и описание","id":"u5l4","unit":4}],"read":{"text":"My grandmother lives in a cottage near the river. Her garden is smaller than ours, but it is the most colourful garden in the village. She grows roses and lavender.","prompt":"What is special about the garden?","options":["It is the biggest.","It is the most colourful in the village.","It has no flowers."],"answer":1,"why":"It is the most colourful garden in the village."},"pages":[40,47]},{"en":"Eat up!","ru":"Подкрепись!","summary":"Питание, количество, жалобы и вежливые ответы","lessons":[{"title":"Countable / uncountable","rule":"Исчисляемые: apple, egg, sandwich — можно посчитать. Неисчисляемые: water, rice, bread в обычном значении. Для них используют a glass of water, a piece of bread.","example":"I bought two apples and some bread.","translate":"Я купила два яблока и немного хлеба.","tip":"Попробуй посчитать предмет: one, two, three...","questions":[{"prompt":"Choose an uncountable noun.","options":["banana","rice","carrot"],"answer":1,"why":"Rice обычно неисчисляемое существительное.","hint":"Его измеряют количеством, а не штуками."},{"prompt":"I need two ___ of water.","options":["glasses","waters","breads"],"answer":0,"why":"Two glasses of water — две чашки/стакана воды.","hint":"Воду считаем через ёмкость."},{"prompt":"There ___ some milk in the fridge.","options":["are","is","be"],"answer":1,"why":"Milk неисчисляемое, согласуется с is.","hint":"Milk — как одно вещество."}],"skill":"Грамматика","id":"u6l1","unit":5},{"title":"Much, many, a few, a little","rule":"Many и a few — с исчисляемыми (books). Much и a little — с неисчисляемыми (time, water). Some/any часто встречаются в утверждениях и вопросах.","example":"We have a few tomatoes but only a little milk.","translate":"У нас есть несколько помидоров, но совсем немного молока.","tip":"Сначала реши: слово исчисляемое или нет.","questions":[{"prompt":"How ___ oranges do we need?","options":["much","many","little"],"answer":1,"why":"Oranges можно посчитать → many.","hint":"Oranges — множественное число."},{"prompt":"There isn’t ___ sugar left.","options":["many","much","a few"],"answer":1,"why":"Sugar неисчисляемое → much.","hint":"Sugar нельзя считать по штукам."},{"prompt":"I have ___ friends in my class.","options":["a little","a few","much"],"answer":1,"why":"Friends можно посчитать → a few.","hint":"Friends — люди по одному."}],"skill":"Грамматика","id":"u6l2","unit":5},{"title":"В ресторане: жалоба и извинение","rule":"Вежливая жалоба: Excuse me, there is a problem with my meal. Извинение: I’m sorry about that. Решение: I’ll bring you a new one. Можно вежливо попросить: Could you replace it, please?","example":"Excuse me, my soup is cold. — I’m sorry. I’ll bring you a hot one.","translate":"Извините, мой суп холодный. — Простите. Сейчас принесу горячий.","tip":"Спокойно назови проблему и предложи решение; избегай грубости.","questions":[{"prompt":"Which is a polite complaint?","options":["Your food is terrible!","Excuse me, my meal is cold.","Go away!"],"answer":1,"why":"Excuse me смягчает просьбу, а проблему называют точно.","hint":"Нужно вежливо."},{"prompt":"A waiter says: “I’m sorry about that.” This is…","options":["an apology","a travel plan","a prediction"],"answer":0,"why":"I’m sorry — извинение.","hint":"Смысл sorry."},{"prompt":"Choose a useful response to a complaint.","options":["I can replace it for you.","Never speak to me.","Tomorrow was yesterday."],"answer":0,"why":"Предложение заменить блюдо помогает решить проблему.","hint":"Нужна помощь гостю."}],"skill":"Разговор","id":"u6l3","unit":5},{"title":"Пишем анкету о питании","rule":"Хорошая анкета содержит понятные короткие вопросы. Используй How often…?, Do you…?, How much/many…? Для частоты подходят every day, twice a week, never.","example":"How often do you eat vegetables?","translate":"Как часто ты ешь овощи?","tip":"Один вопрос — одна мысль; грамматика зависит от того, о чём спрашиваешь.","questions":[{"prompt":"Which question asks about frequency?","options":["How often do you cook?","Where are your keys?","Who is your teacher?"],"answer":0,"why":"How often — как часто.","hint":"Как часто?"},{"prompt":"Choose a good survey question about food.","options":["What colour is your history book?","How many glasses of water do you drink a day?","Where is Monday?"],"answer":1,"why":"Вопрос о количестве выпитой воды относится к теме питания.","hint":"Тема — питание."}],"skill":"Письмо","id":"u6l4","unit":5}],"read":{"text":"Olga wants to eat more vegetables. She buys a few tomatoes and some rice for lunch. She drinks water instead of fizzy drinks and often cooks at home.","prompt":"What does Olga drink instead of fizzy drinks?","options":["Juice.","Coffee.","Water."],"answer":2,"why":"She drinks water instead of fizzy drinks."},"pages":[50,57]},{"en":"Look to the future","ru":"Взгляд в будущее","summary":"Будущее, технологии, условные предложения","lessons":[{"title":"Will: прогнозы и обещания","rule":"Will + глагол используем для предположений, обещаний и спонтанных решений. После will нет -s, -ed или to.","example":"I think people will use cleaner energy in the future.","translate":"Думаю, люди будут использовать более чистую энергию.","tip":"I think / probably часто сочетается с will.","questions":[{"prompt":"I think it ___ rain tomorrow.","options":["will","is","will to"],"answer":0,"why":"Will + rain — прогноз.","hint":"После will сразу глагол."},{"prompt":"I promise I ___ tell anyone.","options":["don’t","won’t","not will"],"answer":1,"why":"Won’t = will not.","hint":"Для обещания не делать что-то: won’t."},{"prompt":"She will ___ us later.","options":["helps","help","helped"],"answer":1,"why":"После will — базовая форма help.","hint":"Без -s."}],"skill":"Грамматика","id":"u7l1","unit":6},{"title":"First Conditional: если, то...","rule":"First Conditional описывает реальное возможное будущее: If + Present Simple, ... will + глагол. После if обычно не ставим will.","example":"If we recycle more, we will make less waste.","translate":"Если мы будем больше перерабатывать, мусора станет меньше.","tip":"If + настоящее, will + будущее в главной части.","questions":[{"prompt":"If it rains, we ___ at home.","options":["stay yesterday","will stay","will staying"],"answer":1,"why":"В главной части нужен will + stay.","hint":"If it rains — условие; потом будет результат."},{"prompt":"If she ___ hard, she will pass.","options":["will study","study","studies"],"answer":2,"why":"После if Present Simple: she studies.","hint":"She + Present Simple."},{"prompt":"Which sentence is correct?","options":["If I will see him, I tell you.","If I see him, I will tell you.","If I saw him, I will told you."],"answer":1,"why":"If + Present Simple, will + verb.","hint":"После if не ставь will."}],"skill":"Грамматика","id":"u7l2","unit":6},{"title":"Предсказания: вероятность","rule":"Sure / definitely — уверенность, probably / perhaps / maybe — вероятность. Делаем прогноз осторожно и подкрепляем причиной.","example":"Perhaps cars will become quieter in the future.","translate":"Возможно, машины станут тише в будущем.","tip":"Maybe — возможно, definitely — определённо.","questions":[{"prompt":"Which word means «возможно»?","options":["never","perhaps","always"],"answer":1,"why":"Perhaps = возможно.","hint":"Не стопроцентная уверенность."},{"prompt":"Choose a prediction.","options":["I went yesterday.","I will probably study online.","I study every Tuesday."],"answer":1,"why":"Will probably описывает вероятное будущее.","hint":"Прогноз о будущем = will."}],"skill":"Лексика и речь","id":"u7l3","unit":6},{"title":"Going to или will: как выбрать будущее","rule":"Going to подходит для намерений и прогнозов с видимыми признаками. Will — для спонтанных решений, обещаний и предположений. Сравни: Look at the clouds! It is going to rain. I think it will rain tomorrow.","example":"Look at those clouds! It is going to rain.","translate":"Посмотри на облака! Сейчас пойдёт дождь.","tip":"Ищи признаки, план или мгновенное решение.","questions":[{"prompt":"Look at the dark clouds! It ___ rain.","options":["will to","is going to","going"],"answer":1,"why":"Прогноз по видимым признакам — is going to.","hint":"Есть очевидные признаки."},{"prompt":"The phone is ringing. — I ___ answer it!","options":["am going","will","was"],"answer":1,"why":"Решение принимается сейчас → will.","hint":"Решение в момент речи."},{"prompt":"I have already bought a ticket. I ___ visit London next week.","options":["am going to","was","will been"],"answer":0,"why":"Билет куплен — есть план, am going to.","hint":"Уже существует план."}],"skill":"Грамматика","id":"u7l4","unit":6}],"read":{"text":"Our class is planning a clean-up day. If the weather is good, we will collect litter in the park. If it rains, we will make posters about recycling in the classroom.","prompt":"What will the class do if it rains?","options":["Make recycling posters.","Cancel school.","Go to the beach."],"answer":0,"why":"If it rains, they will make posters."},"pages":[58,65]},{"en":"The world of work","ru":"Мир профессий","summary":"Профессии, формы глагола, анкеты и звонки","lessons":[{"title":"Verb patterns: enjoy doing, avoid doing","rule":"После enjoy, avoid, finish, mind и ряда других глаголов обычно употребляется форма -ing. Например: enjoy reading, avoid making mistakes. А после can, should, must нужен инфинитив без to: can work.","example":"I enjoy learning English, but I avoid working late.","translate":"Мне нравится учить английский, но я избегаю поздней работы.","tip":"Форму второго глагола определяет первое слово.","questions":[{"prompt":"I enjoy ___ with my classmates.","options":["work","working","to worked"],"answer":1,"why":"Enjoy + -ing → enjoy working.","hint":"После enjoy нужна -ing."},{"prompt":"She avoids ___ late.","options":["being","be","to be"],"answer":0,"why":"Avoid + -ing → being.","hint":"Правило avoid + -ing."},{"prompt":"A nurse should ___ patient.","options":["to be","being","be"],"answer":2,"why":"После модального should используется инфинитив без to.","hint":"Should + bare infinitive."}],"skill":"Грамматика","id":"u8l1","unit":7},{"title":"Verb patterns: want to do, can do","rule":"После want, decide, hope, would like нужен to-инфинитив: want to become, decide to study. После модальных can, must, should — инфинитив без to: can help, must work. После enjoy — -ing. Сравни все три модели.","example":"I want to become a vet, and I can help animals.","translate":"Я хочу стать ветеринаром и могу помогать животным.","tip":"Want → to do; can → do; enjoy → doing.","questions":[{"prompt":"She decided ___ a doctor.","options":["to become","becoming","becomes"],"answer":0,"why":"Decide + to-infinitive.","hint":"После decided обычно to."},{"prompt":"He can ___ English well.","options":["to speak","speaking","speak"],"answer":2,"why":"Can + инфинитив без to.","hint":"После can нет to."},{"prompt":"I would like ___ a programmer.","options":["to be","being","be"],"answer":0,"why":"Would like + to-infinitive.","hint":"Would like + to."}],"skill":"Грамматика","id":"u8l2","unit":7},{"title":"Пишем о себе для работы","rule":"Короткая анкета или письмо: introduce yourself → describe skills → explain interest. Уместны I can..., I am good at..., I would like to....","example":"I am responsible and I can work in a team.","translate":"Я ответственная и умею работать в команде.","tip":"Опиши умение + пример, а не только красивое слово.","questions":[{"prompt":"Complete: I am good ___ working with people.","options":["at","on","in"],"answer":0,"why":"Good at + существительное или -ing.","hint":"Выражение good at."},{"prompt":"Which is a skill?","options":["I can organise events.","I am yesterday.","I have to school."],"answer":0,"why":"I can organise events — реальное умение.","hint":"Skill — то, что умеешь делать."}],"skill":"Письмо и речь","id":"u8l3","unit":7},{"title":"Телефонный разговор: передаём сообщение","rule":"Если нужного человека нет, предложи оставить сообщение: Can I take a message? Уточни имя и номер: Could you spell your name? Обещай передать: I’ll tell her when she comes back.","example":"She is not here at the moment. Can I take a message?","translate":"Её сейчас нет. Могу я принять сообщение?","tip":"Назови, кто звонит, попроси оставить сообщение и повтори детали.","questions":[{"prompt":"Someone calls for Anna, but she is out. What should you say?","options":["Can I take a message?","I hate homework.","I am a bicycle."],"answer":0,"why":"Предлагаем принять сообщение.","hint":"Телефон и отсутствие человека."},{"prompt":"Which question checks how a name is written?","options":["Could you spell your name?","What day is it?","Do you like tea?"],"answer":0,"why":"Spell — произнести по буквам.","hint":"Нужно уточнить написание."},{"prompt":"Choose a promise to pass on a message.","options":["I will give her your message.","I gave a message tomorrow.","I not have message."],"answer":0,"why":"Will + base verb — обещание.","hint":"Обещаем передать."}],"skill":"Разговор","id":"u8l4","unit":7}],"read":{"text":"Artem would like to work with animals. He is learning English to read articles about wildlife. Next month he is going to volunteer at a local animal shelter.","prompt":"Why is Artem learning English?","options":["To become a singer.","To read wildlife articles.","To travel tomorrow."],"answer":1,"why":"To read articles about wildlife."},"pages":[66,73]},{"en":"Love and trust","ru":"Любовь и доверие","summary":"Отношения, Present Perfect, фразовые глаголы","lessons":[{"title":"Present Perfect: опыт и результат","rule":"Present Perfect связывает прошлое и настоящее: have/has + третья форма глагола (V3). Для he/she/it — has, для I/you/we/they — have. Частые слова: just, already, yet, ever, never.","example":"I have just finished my homework.","translate":"Я только что закончила домашнее задание.","tip":"Есть связь с настоящим; нет точной даты вроде yesterday.","questions":[{"prompt":"She ___ already done her homework.","options":["have","has","is"],"answer":1,"why":"She → has; done — третья форма do.","hint":"She → has."},{"prompt":"I have never ___ to Scotland.","options":["been","was","be"],"answer":0,"why":"Have been — побывал; V3 от be — been.","hint":"После have нужна V3."},{"prompt":"___ you ever met a famous person?","options":["Did","Have","Has"],"answer":1,"why":"Have you ever...? — вопрос об опыте.","hint":"You → have."}],"skill":"Грамматика","id":"u9l1","unit":8},{"title":"Phrasal verbs: get on with, fall out, make up","rule":"Фразовый глагол состоит из глагола и частицы. Get on with — ладить, fall out with — поссориться, make up — помириться, look after — заботиться. Запоминай выражение целиком, а не перевод каждого слова.","example":"We fell out yesterday, but we made up today.","translate":"Вчера мы поссорились, но сегодня помирились.","tip":"Не переводи частицы по отдельности: смысл у всего выражения.","questions":[{"prompt":"What does “get on with someone” mean?","options":["ладить с человеком","ехать в автобусе","записывать"],"answer":0,"why":"Get on with someone — хорошо ладить.","hint":"Это об отношениях."},{"prompt":"They argued, but later they ___.","options":["made up","looked after","grew up"],"answer":0,"why":"Make up — помириться после ссоры.","hint":"Ссора закончилась миром."},{"prompt":"I ___ my little brother when our parents are away.","options":["look after","fall out","take off"],"answer":0,"why":"Look after — присматривать, заботиться.","hint":"Это забота."}],"skill":"Грамматика","id":"u9l2","unit":8},{"title":"Согласие и несогласие без ссоры","rule":"Чтобы выразить согласие, используй I agree, You’re right. Для вежливого несогласия: I see your point, but… / I’m not sure I agree. Добавь короткое объяснение своей позиции, а не только yes или no.","example":"I see your point, but I think we should talk first.","translate":"Я понимаю твою мысль, но думаю, нам сначала нужно поговорить.","tip":"Сначала покажи уважение к мнению другого, затем скажи своё.","questions":[{"prompt":"Which expression is polite disagreement?","options":["You are stupid.","I see your point, but I disagree.","Shut up."],"answer":1,"why":"I see your point выражает уважение и несогласие.","hint":"Тон вежливый."},{"prompt":"Choose an expression of agreement.","options":["I agree with you.","I never agree all the time yesterday.","Please turn left."],"answer":0,"why":"I agree with you — я согласен с тобой.","hint":"Agree = соглашаться."},{"prompt":"Which reply gives a reason?","options":["No.","I disagree because the plan is too expensive.","Maybe."],"answer":1,"why":"Because вводит обоснование мнения.","hint":"Есть объяснение."}],"skill":"Разговор","id":"u9l3","unit":8},{"title":"Короткое личное сообщение о проблеме","rule":"В коротком сообщении сначала назови ситуацию, затем чувство, потом предложи действие: I was upset… / Can we talk…? / I hope we can… . Используй дружелюбный тон и понятный порядок.","example":"I am sorry about yesterday. Can we talk after school?","translate":"Прости за вчерашнее. Можем поговорить после школы?","tip":"Три шага: ситуация → чувство → решение.","questions":[{"prompt":"Which message is polite and clear?","options":["Sorry about yesterday. Can we talk?","YOU ARE BAD!!!","No never always."],"answer":0,"why":"Вежливое извинение и предложение поговорить.","hint":"Нужен мирный выход."},{"prompt":"Choose the best opening of a short friendly message.","options":["Hi, Kate!","To the Ministry of Education","Financial Report 2020"],"answer":0,"why":"Hi, Kate! — дружеское обращение.","hint":"Пишешь подруге."}],"skill":"Письмо","id":"u9l4","unit":8}],"read":{"text":"Dasha felt disappointed after an argument with her friend. Her brother advised her to talk calmly. She wrote a kind message, and they agreed to meet after school.","prompt":"What did her brother advise her to do?","options":["Talk calmly.","Stop going to school.","Ignore everybody."],"answer":0,"why":"Her brother advised her to talk calmly."},"pages":[76,83]},{"en":"The media","ru":"Средства массовой информации","summary":"СМИ, Passive Voice, письмо в журнал","lessons":[{"title":"Passive Voice: как образуется","rule":"Пассивный залог показывает, что происходит с предметом. Present Simple Passive: am/is/are + V3. Past Simple Passive: was/were + V3. Present Perfect Passive: has/have been + V3.","example":"The article was published yesterday. Today it is read by many students.","translate":"Статья была опубликована вчера. Сегодня её читают многие школьники.","tip":"Для Passive всегда найди форму be + V3.","questions":[{"prompt":"Newspapers ___ sold in this shop every day.","options":["are","were","have"],"answer":0,"why":"Every day → Present Simple Passive: are sold.","hint":"Every day — обычное действие."},{"prompt":"The story ___ reported yesterday.","options":["is","was","has"],"answer":1,"why":"Yesterday → Past Simple Passive: was reported.","hint":"Вчера, прошлое → was."},{"prompt":"The messages have ___ sent.","options":["be","being","been"],"answer":2,"why":"Present Perfect Passive: have been + V3.","hint":"После have в пассиве используется been."}],"skill":"Грамматика","id":"u10l1","unit":9},{"title":"Факты и мнения в новостях","rule":"Факт можно проверить по источникам; мнение выражает чью-то оценку. Важно замечать слова think, believe, best, terrible и проверять источник информации.","example":"The match started at six. / I think it was the best match.","translate":"Матч начался в шесть. / Думаю, это был лучший матч.","tip":"Числа и события проверяемы; оценка — мнение.","questions":[{"prompt":"Which is an opinion?","options":["The train left at eight.","The city has two museums.","This is the greatest film ever."],"answer":2,"why":"Greatest — оценка, а не объективно установленный факт.","hint":"Есть эмоциональная оценка."},{"prompt":"What should you do with a surprising online claim?","options":["Check another reliable source.","Share it immediately.","Believe it if it is popular."],"answer":0,"why":"Проверяй источник и подтверждения.","hint":"Нужна проверка информации."},{"prompt":"Choose a reporting verb.","options":["report","sleep","cook"],"answer":0,"why":"Report значит сообщать/освещать событие.","hint":"Связано с news."}],"skill":"Грамматика","id":"u10l2","unit":9},{"title":"Пишем письмо в журнал","rule":"В письме в журнал обозначь тему: I am writing about… Затем сформулируй мнение, приведи один аргумент и завершение. Для аргумента используй because; для предложения — I think… / In my opinion… .","example":"Dear Editor, I am writing about your article on school clubs.","translate":"Уважаемый редактор, я пишу по поводу вашей статьи о школьных кружках.","tip":"Обращение → тема → мнение с аргументом → вежливое завершение.","questions":[{"prompt":"Which opening suits a letter to a magazine?","options":["Dear Editor,","Hey bro!!!","Good night, sofa"],"answer":0,"why":"Для письма редактору уместно Dear Editor.","hint":"Пишем редактору."},{"prompt":"Which phrase introduces an opinion?","options":["In my opinion,","At half past Monday","The blue quickly"],"answer":0,"why":"In my opinion — по моему мнению.","hint":"Личная позиция."},{"prompt":"Choose a clear reason.","options":["Because I think students need more books.","Purple fast yesterday because.","No, no, no."],"answer":0,"why":"Because поясняет причину мнения.","hint":"Есть причина и законченная мысль."}],"skill":"Письмо","id":"u10l3","unit":9}],"read":{"text":"A school newspaper published an article about a new sports club on Tuesday. The article included interviews with two students. The editor reminded readers to check information before sharing it.","prompt":"When was the article published?","options":["On Friday.","On Tuesday.","On Sunday."],"answer":1,"why":"The article was published on Tuesday."},"pages":[84,91]}];
const BASE=[
{title:'To be: am / is / are',unit:-1,id:'base1',questions:[{prompt:'I ___ at home now.',options:['am','is','are'],answer:0,hint:'I + am.',why:'I am — я есть/нахожусь.'},{prompt:'My friends ___ happy.',options:['is','are','am'],answer:1,hint:'Friends — множественное число.',why:'Friends → are.'}]},
{title:'Do / does: вопросы',unit:-1,id:'base2',questions:[{prompt:'___ she like music?',options:['Do','Does','Is'],answer:1,hint:'She — третье лицо.',why:'Does she like...? После does глагол без -s.'},{prompt:'___ you go to school by bus?',options:['Do','Does','Is'],answer:0,hint:'You → do.',why:'Do you...? — Present Simple.'}]},
{title:'Past Simple: основы',unit:-1,id:'base3',questions:[{prompt:'Yesterday we ___ a film.',options:['watch','watched','watching'],answer:1,hint:'Yesterday = прошлое.',why:'Watched — прошедшее время правильного глагола.'},{prompt:'They ___ to school last Monday.',options:['went','go','goes'],answer:0,hint:'Go — неправильный глагол.',why:'Go → went в Past Simple.'}]},
{title:'Порядок слов в предложении',unit:-1,id:'base4',questions:[{prompt:'Choose the correct sentence.',['options']:['She often reads books.','Often she books reads.','Reads she often books.'],answer:0,hint:'Сначала подлежащее she, потом глагол.',why:'She often reads books — естественный порядок слов.'},{prompt:'Choose a question.',['options']:['Where you live?','Where do you live?','Where does you live?'],answer:1,hint:'Where + do + you + verb?',why:'Where do you live? — правильный вопрос.'}]}
];
BASE[0].rule='Am используется с I; is — с he/she/it; are — с you/we/they. В вопросе am/is/are ставим перед подлежащим.';BASE[0].example='I am ready. She is happy. They are at school.';BASE[0].translate='Я готова. Она счастлива. Они в школе.';BASE[0].tip='Запомни три пары: I–am, she–is, they–are.';
BASE[1].rule='Для вопросов о привычках используем Do/Does + подлежащее + глагол без окончания. Does — с he/she/it; do — с I/you/we/they.';BASE[1].example='Do you like music? Does she play the piano?';BASE[1].translate='Ты любишь музыку? Она играет на пианино?';BASE[1].tip='Does уже содержит -s: основной глагол без -s.';
BASE[2].rule='Past Simple — завершённое прошлое. Для правильных глаголов прибавляем -ed, неправильные учим: go–went, do–did, see–saw.';BASE[2].example='We watched a film and went home.';BASE[2].translate='Мы посмотрели фильм и пошли домой.';BASE[2].tip='Ищи yesterday, last week, ago.';
BASE[3].rule='Обычное утверждение: подлежащее + глагол + остальные слова. Вопрос в Present Simple: вопросительное слово + do/does + подлежащее + глагол?';BASE[3].example='She often reads books. Where do you live?';BASE[3].translate='Она часто читает книги. Где ты живёшь?';BASE[3].tip='Не копируй русский порядок слов: смотри на подлежащее и помощник.';
BASE.forEach(b=>{b.skill='Повторение базы'});
const allLessons=[...BASE,...U.flatMap(u=>u.lessons)];const STORE='MIRA_FORWARD8_FULL_V02';
let state={diagnostics:[],answers:[],done:[],read:[],seconds:0};
// Free edition: the device-local progress adapter restores validated state.
let page='home',unitIndex=0,lessonId='',step=0,quizChosen=null,quizDone=false,hintShown=false,readIndex=-1,readChosen=null,readDone=false,diagIndex=0,diagChoice=null,diagRevealed=false,diagRun=[],diagIds=[];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){window.dispatchEvent(new CustomEvent('mira:progress'));}
function speak(text,lang='en-GB',rate=.85){if(window.Mira)window.Mira.speak(text,lang.startsWith('en')?{lang}:{lang,rate});else alert('Мира ещё подключается. Попробуй через секунду.')}
function getLesson(id){return allLessons.find(l=>l.id===id)}
function unitCompleted(i){const ls=U[i].lessons;return ls.filter(l=>state.done.includes(l.id)).length}
function record(id,unit,ok,hint){state.answers.push({id,unit,ok,hint,at:Date.now()});if(state.answers.length>1500)state.answers=state.answers.slice(-1500);save()}
function accuracy(a){return a.length?Math.round(a.filter(x=>x.ok).length/a.length*100):0}
function go(target){page=target;$$('.page').forEach(n=>n.classList.toggle('on',n.id===target));$$('[data-go]').forEach(n=>n.classList.toggle('active',n.dataset.go===target));if(target==='home')renderHome();if(target==='catalog')renderCatalog();if(target==='foundation')renderFoundation();if(target==='unit')renderUnit();if(target==='lesson')renderLesson();if(target==='reading')renderReading();if(target==='diagnostic')renderDiagnostic();if(target==='parent')renderParent();window.scrollTo({top:0,behavior:'instant'});window.dispatchEvent(new CustomEvent('mira:progress'));}
function renderHome(){const a=state.answers;$('#hmLessons').textContent=state.done.filter(id=>id.startsWith('u')).length;$('#hmAccuracy').textContent=a.length?accuracy(a)+'%':'—';$('#hmReading').textContent=state.read.length+'/10';const last=state.diagnostics.at(-1);$('#homePersonal').textContent=last?`Последняя диагностика: ${last.score}/${last.total}`:'Начни с короткого теста';const weak=weakestUnit();$('#homeRecommendation').textContent=weak!==null?`Полезно повторить Unit ${weak+1}: ${U[weak].ru}.`:'После теста Мира предложит, что повторять сначала.'}
function weakestUnit(){let scores=[];for(let i=0;i<10;i++){const a=state.answers.filter(a=>a.unit===i);if(a.length)scores.push([i,accuracy(a),a.length])};let t=state.diagnostics.at(-1);if(t){for(let i=0;i<10;i++){const r=t.unitHits[i];if(r?.total)scores.push([i,Math.round(r.ok/r.total*100),r.total])}}if(!scores.length)return null;scores.sort((a,b)=>a[1]-b[1]||b[2]-a[2]);return scores[0][0]}
function renderFoundation(){$('#foundationHost').innerHTML=BASE.map((l,i)=>`<button class="listrow" data-open-lesson="${l.id}"><div><b>${i+1}. ${esc(l.title)}</b><span>Укрепляем базу · 2 задания</span></div><div class="status">${state.done.includes(l.id)?'✓ Пройдено':'Начать →'}</div></button>`).join('')}
function renderCatalog(){$('#unitsGrid').innerHTML=U.map((u,i)=>`<button class="card unitcard" data-open-unit="${i}"><span class="num">UNIT ${String(i+1).padStart(2,'0')} · стр. ${u.pages.join('–')}</span><strong class="unit-name">${esc(u.en)}</strong><span class="muted unit-translation">${esc(u.ru)}</span><span class="topic-headline">${esc(u.summary)}</span><div class="progress"><i style="width:${unitCompleted(i)/u.lessons.length*100}%"></i></div><small class="unit-meta">${unitCompleted(i)} из ${u.lessons.length} уроков</small></button>`).join('')}
function renderUnit(){const u=U[unitIndex];$('#unitHost').innerHTML=`<div class="card"><div class="eyebrow">UNIT ${unitIndex+1} · FORWARD 8 · стр. ${u.pages.join('–')}</div><h1 style="font-size:clamp(34px,4.5vw,58px)">${esc(u.en)}</h1><p class="muted topic-explainer">${esc(u.ru)} · ${esc(u.summary)}</p><div class="notice">Раздел соответствует тематике Forward 8, стр. ${u.pages.join('–')}. Объяснения и упражнения — наши. Номер страницы указывает раздел, а не конкретное упражнение.</div><div style="margin-top:23px">${u.lessons.map((l,i)=>`<button class="listrow" data-open-lesson="${esc(l.id)}"><div><b>${i+1}. ${esc(l.title)}</b><span>${esc(l.skill)} · 5–8 минут · ${l.questions.length} задания · стр. ${u.pages.join('–')}</span></div><div class="status">${state.done.includes(l.id)?'✓ Пройдено':'Начать →'}</div></button>`).join('')}</div><div class="actions"><button class="btn" data-go="reading">📖 Читать короткие тексты</button></div></div>`}
function renderLesson(){const l=getLesson(lessonId);if(!l)return;const u=l.unit<0?{en:'Повторяем основы',ru:'5–7 класс'}:U[l.unit];let q=l.questions[step];const feedback=quizDone?`<div class="notice ${quizChosen===q.answer?'good':'bad'}" style="margin-top:15px"><b>${quizChosen===q.answer?'✓ Отлично!':'💜 Ничего страшного.'}</b><p style="margin:7px 0 0">${esc(q.why)}</p></div>`:'';
$('#lessonHost').innerHTML=`<div class="card"><div class="lessonhead"><img src="assets/mira-0.webp" alt="Мира"><div><div class="eyebrow">${l.unit<0?"ОСНОВЫ":"UNIT "+(l.unit+1)} · ${esc(u.en)}</div><h2 style="margin:5px 0 0">${esc(l.title)}</h2></div></div><p class="theory">${esc(l.rule)}</p><div class="lessonexample"><div class="eyebrow">ПРИМЕР</div><b>${esc(l.example)}</b><p>${esc(l.translate)}</p><div class="actions"><button class="btn" id="sayExample">🔊 Послушать по-английски</button><button class="btn" id="sayRule">🎧 Мира объяснит по-русски</button></div></div><div class="notice"><b>Подсказка от Миры:</b> ${esc(l.tip)}</div><div class="qbox"><div class="eyebrow">ПОПРОБУЙ САМА · ${step+1} ИЗ ${l.questions.length}</div><h3 style="margin:9px 0 18px">${esc(q.prompt)}</h3><div class="options">${q.options.map((o,i)=>`<button class="option ${quizDone?(i===q.answer?'correct':i===quizChosen?'wrong':''):''}" data-choose="${i}" ${quizDone?'disabled':''}><span class="optlabel">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div><div class="actions">${!quizDone?`<button class="btn" id="hintBtn">💡 ${hintShown?'Скрыть подсказку':'Дай подсказку'}</button>`:`<button class="btn primary" id="nextTask">${step===l.questions.length-1?'Завершить урок ✓':'Следующий вопрос →'}</button>`}</div>${hintShown&&!quizDone?`<div class="notice" style="margin-top:13px">${esc(q.hint)}</div>`:''}${feedback}</div></div>`;
$('#sayExample').onclick=()=>speak(l.example,'en-GB',.82);$('#sayRule').onclick=()=>speak(l.rule,'ru-RU',.94);let h=$('#hintBtn');if(h)h.onclick=()=>{hintShown=!hintShown;renderLesson()};let n=$('#nextTask');if(n)n.onclick=()=>{if(step===l.questions.length-1){if(!state.done.includes(l.id))state.done.push(l.id);save();go(l.unit<0?'foundation':'unit');return}step++;quizChosen=null;quizDone=false;hintShown=false;renderLesson();save()}}
function chooseLesson(i){if(quizDone)return;let l=getLesson(lessonId);let q=l.questions[step];quizChosen=i;quizDone=true;record(l.id,l.unit,i===q.answer,hintShown);renderLesson()}
function renderReading(){const host=$('#readGrid');host.innerHTML=U.map((u,i)=>`<button class="card unitcard" data-open-read="${i}"><span class="num">TEXT ${i+1}</span><strong>${esc(u.en)}</strong><small>${esc(u.ru)}</small><span class="status">${state.read.includes(i)?'✓ Прочитано':'Читать →'}</span></button>`).join('');renderReadDetail()}
function renderReadDetail(){if(readIndex<0){$('#readHost').innerHTML='';return}const u=U[readIndex],r=u.read;$('#readHost').innerHTML=`<div class="card" style="margin-top:19px"><div class="eyebrow">READING · UNIT ${readIndex+1}</div><h2>${esc(u.en)}</h2><p class="readtext">${esc(r.text)}</p><div class="actions"><button class="btn" id="readAloud">🔊 Послушать текст</button></div><div class="qbox"><div class="eyebrow">ПРОВЕРКА ПОНИМАНИЯ</div><h3>${esc(r.prompt)}</h3><div class="options">${r.options.map((o,i)=>`<button class="option ${readDone?(i===r.answer?'correct':i===readChosen?'wrong':''):''}" data-read-choice="${i}" ${readDone?'disabled':''}>${esc(o)}</button>`).join('')}</div>${readDone?`<div class="notice ${readChosen===r.answer?'good':'bad'}" style="margin-top:16px">${esc(r.why)}</div>`:''}</div></div>`;$('#readAloud').onclick=()=>speak(r.text,'en-GB',.86)}
function makeDiag(){let entries=[];BASE.forEach(b=>entries.push({q:b.questions[0],unit:-1,label:'Основа'}));U.forEach((u,i)=>{entries.push({q:u.lessons[0].questions[0],unit:i,label:u.en});if(i<6)entries.push({q:u.lessons[1].questions[0],unit:i,label:u.en})});return entries}
const D=makeDiag();
function renderDiagnostic(){if(diagIndex>=D.length){showDiagResult();return}let d=D[diagIndex],r=d.q;$('#dqnum').textContent=`${diagIndex+1} / ${D.length}`;$('#diagnosticHost').innerHTML=`<div class="eyebrow">${esc(d.label)}</div><div class="progress" style="margin:14px 0 25px"><i style="width:${diagIndex/D.length*100}%"></i></div><h2>${esc(r.prompt)}</h2><p class="muted">Выбери один ответ. Если сомневаешься, выбирай как думаешь: здесь нет школьных отметок.</p><div class="options">${r.options.map((o,i)=>`<button class="option ${diagRevealed?(i===r.answer?'correct':i===diagChoice?'wrong':''):''}" data-diag-choice="${i}" ${diagRevealed?'disabled':''}>${esc(o)}</button>`).join('')}</div>${diagRevealed?`<div class="notice ${diagChoice===r.answer?'good':'bad'}" style="margin-top:16px">${esc(r.why)}</div><div class="actions"><button class="btn primary" id="diagNext">${diagIndex===D.length-1?'Посмотреть результат →':'Следующий вопрос →'}</button></div>`:''}`;
let n=$('#diagNext');if(n)n.onclick=()=>{diagIndex++;diagChoice=null;diagRevealed=false;if(diagIndex>=D.length){let hits={};for(let j=0;j<D.length;j++){let k=D[j].unit;const s=hits[k]||(hits[k]={ok:0,total:0});s.total++;if(diagRun[j])s.ok++}state.diagnostics.push({score:diagRun.filter(Boolean).length,total:D.length,unitHits:hits,at:Date.now()});save();showDiagResult()}else renderDiagnostic()}}
function showDiagResult(){const t=state.diagnostics.at(-1);if(!t){diagIndex=0;renderDiagnostic();return}let sorted=Object.entries(t.unitHits).filter(([k])=>Number(k)>=0).sort((a,b)=>a[1].ok/a[1].total-b[1].ok/b[1].total);const weak=sorted.slice(0,3).map(([i])=>U[Number(i)].ru);$('#dqnum').textContent='Готово';$('#diagnosticHost').innerHTML=`<div class="eyebrow">ДИАГНОСТИКА ЗАВЕРШЕНА</div><h1 style="color:#ffc1ed">${t.score} из ${t.total}</h1><p class="muted">Это не оценка. По этим вопросам видно, с каких тем лучше начать.</p><div class="notice">${t.unitHits['-1']?.ok<4?'Похоже, стоит повторить базовую грамматику: am/is/are, do/does и Past Simple. ':''}Сейчас полезно вернуться к темам: <b>${esc(weak.join(' · '))}</b>.</div><div class="actions"><button class="btn primary" data-go="catalog">К урокам →</button><button class="btn" data-go="foundation">Повторить основы →</button><button class="btn" data-go="parent">Отчёт маме</button><button class="btn" id="diagAgain">Пройти заново</button></div>`;$('#diagAgain').onclick=resetDiag}
function resetDiag(){diagIndex=0;diagRun=[];diagChoice=null;diagRevealed=false;renderDiagnostic()}
function renderParent(){const a=state.answers,diagnostic=state.diagnostics.at(-1);$('#parentMetrics').innerHTML=[['${MIN}','Активных минут'],[state.done.filter(id=>id.startsWith('u')).length+'/38','Уроков Forward 8'],[a.length?accuracy(a)+'%':'—','Верных ответов'],[state.read.length+'/10','Текстов прочитано'],[state.diagnostics.length,'Диагностик']].map(([n,t])=>`<div class="card metric"><b>${n}</b><span>${t}</span></div>`).join('').replace('${MIN}',String(Math.round(state.seconds/60)));$('#parentTopics').innerHTML=U.map((u,i)=>{let t=a.filter(x=>x.unit===i),got=t.length?accuracy(t):null,complete=unitCompleted(i);return `<div class="reportline"><div><b>Unit ${i+1} · ${esc(u.en)}</b><span>${got===null?'нет практики':got+'%'} · ${complete}/${u.lessons.length}</span></div><div class="progress"><i style="width:${complete/u.lessons.length*100}%"></i></div></div>`}).join('');const weak=weakestUnit();const base=diagnostic?.unitHits?.['-1'];$('#parentAdvice').innerHTML=`<p>${diagnostic?`Диагностика: <b>${diagnostic.score}/${diagnostic.total}</b>.`:'Диагностика ещё не пройдена.'}</p><p>${base?.total&&base.ok<base.total?'Есть признаки пробелов в основах: to be, do/does или Past Simple. Их стоит повторять перед сложными темами.':''}</p><p>${weak===null?'Сначала предложите пройти мягкую диагностику из 20 вопросов.':`Рекомендация: повторить <b>Unit ${weak+1} — ${esc(U[weak].en)}</b>. Ошибки по отдельным заданиям не означают, что весь раздел не освоен.`}</p><p>Ритм: по <b>10–15 минут</b>, несколько раз в неделю. Раз в 7–10 дней повторите сложный урок и сравните самостоятельные попытки.</p><p class="small">Попыток с подсказкой: ${a.filter(x=>x.hint).length}. С ошибкой: ${a.filter(x=>!x.ok).length}. Эти показатели отражают только работу в этом приложении.</p>`}
const hwUnit=$('#hwUnit');U.forEach((u,i)=>{const op=document.createElement('option');op.value=i;op.textContent=`Unit ${i+1} — ${u.en}`;hwUnit.append(op)});
$('#hwHelp').onclick=()=>{let i=+hwUnit.value,k=$('#hwKind').value,u=U[i];$('#hwAdvice').innerHTML=`<div class="eyebrow">МИРА ПОДСКАЗЫВАЕТ</div><h3>${esc(u.en)} · ${esc(u.ru)}</h3><div class="notice">${k==='grammar'?'1. Найди подлежащее. 2. Посмотри на указатель времени. 3. Выбери нужную форму глагола. 4. Проверь отрицание и вопрос.':k==='reading'?'1. Прочитай вопрос до текста. 2. Найди имена, даты и ключевые слова. 3. Перечитай предложение с ответом. 4. Проверь, что ответ следует из текста.':'1. Определи кому и зачем пишешь. 2. Составь план из 3 мыслей. 3. Напиши короткие понятные предложения. 4. Проверь времена, артикли и орфографию.'}</div><div class="actions"><button class="btn primary" id="goHelpUnit">Разобрать темы Unit ${i+1} →</button></div><p class="small">Приложение подбирает готовую тему и похожие примеры; конкретное упражнение из учебника оно не разбирает.</p>`;$('#goHelpUnit').onclick=()=>{unitIndex=i;go('unit')}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-go],[data-open-unit],[data-open-lesson],[data-open-read],[data-choose],[data-diag-choice],[data-read-choice]');if(!el)return;if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.openUnit!==undefined){unitIndex=+el.dataset.openUnit;go('unit');return}if(el.dataset.openLesson){lessonId=el.dataset.openLesson;unitIndex=Math.max(0,getLesson(lessonId).unit);$('#lessonBack').dataset.go=getLesson(lessonId).unit<0?'foundation':'unit';$('#lessonBack').textContent=getLesson(lessonId).unit<0?'← К основам':'← К разделу';step=0;quizChosen=null;quizDone=false;hintShown=false;go('lesson');return}if(el.dataset.openRead!==undefined){readIndex=+el.dataset.openRead;readChosen=null;readDone=false;renderReadDetail();save();$('#readHost').scrollIntoView({behavior:'smooth'});return}if(el.dataset.choose!==undefined){chooseLesson(+el.dataset.choose);return}if(el.dataset.diagChoice!==undefined){if(diagRevealed)return;diagChoice=+el.dataset.diagChoice;diagRun[diagIndex]=diagChoice===D[diagIndex].q.answer;diagRevealed=true;renderDiagnostic();save();return}if(el.dataset.readChoice!==undefined){if(readDone)return;readChosen=+el.dataset.readChoice;readDone=true;if(readChosen===U[readIndex].read.answer&&!state.read.includes(readIndex)){state.read.push(readIndex);save()}renderReadDetail();save();return}});
let lastActivity=Date.now();window.addEventListener('mira:activity',()=>{lastActivity=Date.now()});document.addEventListener('pointerdown',()=>{lastActivity=Date.now()},{passive:true});document.addEventListener('keydown',()=>{lastActivity=Date.now()});setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-lastActivity<120000){state.seconds+=15;save()}},15000);

const PAGE_BLOCKS=[...U.map((u,i)=>({a:u.pages[0],b:u.pages[1],i,name:u.en})),
{a:30,b:31,i:2,name:'Consolidation 1 · повторение Units 1–3'},
{a:48,b:49,i:4,name:'Consolidation 2 · повторение Units 4–5'},
{a:74,b:75,i:7,name:'Consolidation 3 · повторение Units 6–8'},
{a:92,b:95,i:9,name:'Consolidation 4 · повторение Units 9–10'},
{a:96,b:103,i:0,name:'Dialogue of Cultures · культурные материалы'},
{a:104,b:112,i:0,name:'EXAM FOCUS · экзаменационные навыки'},
{a:113,b:115,i:0,name:'Student activities · разговорные карточки'}];
function findBookPage(){
 const n=Number(document.querySelector('#bookPage').value),area=document.querySelector('#pageFinderResult');
 if(!Number.isInteger(n)||n<1||n>140){area.textContent='Введи номер страницы от 1 до 140.';return}
 const b=PAGE_BLOCKS.find(b=>n>=b.a&&n<=b.b);
 if(b){area.innerHTML=`<div class="page-find-result"><strong>Страница ${n}: ${esc(b.name)}</strong><span>${n>115?'Эта часть ещё не проверена по полному изданию 2023 года.':'Ориентировочная тема: сверь её со своим изданием. Здесь самостоятельные объяснения и задания.'}</span><button class="btn primary" id="pageOpenUnit">Открыть тему →</button></div>`;document.querySelector('#pageOpenUnit').onclick=()=>{unitIndex=b.i;go('unit')};return}
 if(n<=5){area.textContent='Страницы 1–5: обложка, содержание и вступление. Начать лучше с Unit 1.';return}
 if(n>=116){area.textContent=`Страница ${n} относится к словарю или приложениям (по оглавлению). Эта часть не сверена по экземпляру 2023 года. Изучение доступно по темам Units 1–10.`;return}
 area.textContent='Для этой страницы нужно дополнительное сопоставление с полным учебником.';
}
document.querySelector('#findBookPage').onclick=findBookPage;
document.querySelector('#bookPage').addEventListener('keydown',e=>{if(e.key==='Enter')findBookPage()});

renderHome();renderCatalog();resetDiag();renderReading();


window.MiraLearning={
 catalog(){return JSON.parse(JSON.stringify({units:U,foundation:BASE}));},
 openLesson(id){const lesson=getLesson(id);if(!lesson)return false;lessonId=id;unitIndex=Math.max(0,lesson.unit);step=0;quizChosen=null;quizDone=false;hintShown=false;$('#lessonBack').dataset.go=lesson.unit<0?'foundation':'unit';go('lesson');return true;},

 snapshot(){return {...JSON.parse(JSON.stringify(state)),position:{page,unitIndex,lessonId,step,readIndex,quizChosen,quizDone,hintShown,readChosen,readDone,diagIndex,diagChoice,diagRevealed,diagRun,updatedAt:Date.now()}}},
 restore(value){
  state={diagnostics:[],answers:[],done:[],read:[],seconds:0,...value};if(!Number.isFinite(state.seconds))state.seconds=0;
  for(const k of ['diagnostics','answers','done','read'])if(!Array.isArray(state[k]))state[k]=[];
  const p=value.position||{};unitIndex=Math.max(0,Math.min(9,Number(p.unitIndex)||0));
  lessonId=getLesson(p.lessonId)?p.lessonId:'';step=Math.max(0,Math.min((getLesson(lessonId)?.questions.length||1)-1,Number(p.step)||0));
  readIndex=Number.isInteger(p.readIndex)&&p.readIndex>=0&&p.readIndex<10?p.readIndex:-1;
  quizChosen=Number.isInteger(p.quizChosen)&&p.quizChosen>=0&&p.quizChosen<3?p.quizChosen:null;quizDone=!!p.quizDone&&quizChosen!==null;hintShown=!!p.hintShown;
  readChosen=Number.isInteger(p.readChosen)&&p.readChosen>=0&&p.readChosen<3?p.readChosen:null;readDone=!!p.readDone&&readChosen!==null;
  diagIndex=Math.max(0,Math.min(D.length,Number(p.diagIndex)||0));diagRun=Array.isArray(p.diagRun)?p.diagRun.map(Boolean).slice(0,D.length):[];
  diagChoice=Number.isInteger(p.diagChoice)&&p.diagChoice>=0&&p.diagChoice<3?p.diagChoice:null;diagRevealed=!!p.diagRevealed&&diagChoice!==null;
  const allowed=['home','catalog','foundation','unit','lesson','reading','diagnostic','homework','mentor','parent'];
  let target=allowed.includes(p.page)?p.page:'home';if(target==='lesson'&&!lessonId)target='home';go(target);
 },
 openPage(n,exercise=''){const input=document.querySelector('#bookPage');input.value=String(n);go('catalog');findBookPage();window.dispatchEvent(new CustomEvent('mira:page',{detail:{page:n,exercise}}));return {page:n,exercise,exactExerciseKnown:false,message:exercise?'Точное упражнение в приложении не загружено. Можно открыть похожий самостоятельный урок.':'Открыта тематическая карта. Точное издание пока не подтверждено.'}},
 topic(){const l=getLesson(lessonId);if(l&&(page==='lesson'||page==='mentor'))return JSON.stringify({source:'Самостоятельный тематический урок MIRA, а не текст учебника',title:l.title,rule:l.rule,example:l.example,question:l.questions[step]?.prompt,options:l.questions[step]?.options,studentChoice:quizChosen});return 'Forward 8, Unit '+(unitIndex+1)+': '+U[unitIndex].en}
};
